(() => {
  "use strict";

  /**
   * JEN PLAY HOUSE — UPDATE CARD EXPORT
   * Additive patch only. Does not replace the existing Updates UI.
   *
   * Public API:
   *   JenUpdateCardExport.export(update)
   *   JenUpdateCardExport.render(update)
   *
   * Supported post types:
   *   Text, Photo, Carousel, Video, Voice Note / Audio
   *
   * Layout rules:
   * - Logo only, centered at top.
   * - No phone status bar, signal, Wi-Fi, battery, etc.
   * - Website fonts are reused. No font import.
   * - Text & voice-note cards use adaptive height: no large empty space.
   * - Photo / carousel / video = 1080 × 1350 (4:5).
   * - Carousel exports each slide separately.
   * - Small disclaimer at bottom.
   */

  const CFG = Object.freeze({
    width: 1080,
    mediaHeight: 1350,
    background: "#fbfaf8",
    ink: "#171717",
    muted: "#77736f",
    line: "#e7e2dc",
    soft: "#f2eee9",
    side: 56,
    logoBand: 96,
    footer: 64,
    frameInset: 18,
    frameRadius: 22,
    frameColor: "#d8d4cf",
    frameInnerColor: "#ece8e3",
    disclaimer: "This is made for roleplay purpose — Jen Play House App 2026",
    logoUrl: 'data:image/png;base64,'
  });

  const get = (obj, keys, fallback = "") => {
    for (const key of keys) {
      const value = obj?.[key];
      if (value !== undefined && value !== null && String(value).trim() !== "") return value;
    }
    return fallback;
  };

  const getType = update =>
    String(get(update, ["Post Type", "postType", "type", "Type"], "Text"))
      .trim()
      .toLowerCase();

  function asText(value) {
    if (value === undefined || value === null) return "";
    if (typeof value === "string" || typeof value === "number") {
      return String(value).trim();
    }
    return "";
  }

  const getName = update => {
    const direct = [
      update?.["Author Name"],
      update?.["Display Name"],
      update?.displayName,
      update?.Name,
      update?.name
    ].map(asText).find(Boolean);

    if (direct) return direct;

    const author = update?.Author;
    if (author && typeof author === "object") {
      const nested = [
        author["Display Name"],
        author.Name,
        author.name,
        author.displayName
      ].map(asText).find(Boolean);

      if (nested) return nested;
    }

    return "Jeniffer Nora";
  };

  const getRole = update => {
    const direct = [
      update?.Role,
      update?.role,
      update?.Position,
      update?.position,
      update?.Category,
      update?.category
    ].map(asText).find(Boolean);

    const author = update?.Author;
    const nested = author && typeof author === "object"
      ? [
          author.Role,
          author.role,
          author.Position,
          author.position
        ].map(asText).find(Boolean)
      : "";

    const raw = direct || nested || "Artist";

    // The export card should show the public posting role, not admin/owner wording.
    if (/artist/i.test(raw)) return "Artist";
    if (/j[- ]?team/i.test(raw)) return "J-Team";

    return raw;
  };

  const getAvatar = update => {
    const direct = [
      update?.["Author Photo"],
      update?.Avatar,
      update?.Photo,
      update?.photo,
      update?.["Profile Photo"],
      update?.profilePhoto
    ].map(asText).find(Boolean);

    if (direct) return direct;

    const author = update?.Author;
    if (author && typeof author === "object") {
      return [
        author.Photo,
        author.photo,
        author.Avatar,
        author.avatar,
        author["Profile Photo"]
      ].map(asText).find(Boolean) || "";
    }

    return "";
  };

  const getText = update =>
    String(get(update, ["Text", "text", "Caption", "caption", "Post Text", "postText"], ""));

  const getDate = update =>
    String(get(update, ["Date", "date", "Created At", "createdAt", "Timestamp", "timestamp"], ""));

  const getDuration = update =>
    String(get(update, ["Duration", "duration", "Audio Duration", "audioDuration"], ""));

  const getThumbnail = update =>
    String(get(update, ["Thumbnail", "thumbnail", "Poster", "poster", "Video Thumbnail", "videoThumbnail"], ""));

  function getMedia(update) {
    if (Array.isArray(update?.media)) return update.media.filter(Boolean).map(String);

    const keys = [
      "Media 1", "Media1", "media1",
      "Media 2", "Media2", "media2",
      "Media 3", "Media3", "media3",
      "Media 4", "Media4", "media4"
    ];

    const output = [];
    for (const key of keys) {
      const value = update?.[key];
      if (value && !output.includes(String(value))) output.push(String(value));
    }
    return output;
  }

  function bodyFont() {
    try {
      return getComputedStyle(document.body).fontFamily || "Arial, sans-serif";
    } catch {
      return "Arial, sans-serif";
    }
  }

  function headingFont() {
    const selectors = [".brand-name", ".section-heading h2", "h1", "h2"];
    for (const selector of selectors) {
      const el = document.querySelector(selector);
      if (el) {
        const family = getComputedStyle(el).fontFamily;
        if (family) return family;
      }
    }
    return bodyFont();
  }

  const f = (size, weight = 400, family = bodyFont()) =>
    `${weight} ${size}px ${family}`;

  function canvas(width, height, scale = 1) {
    const node = document.createElement("canvas");
    node.width = Math.round(width * scale);
    node.height = Math.round(height * scale);

    const ctx = node.getContext("2d");
    if (scale !== 1) ctx.scale(scale, scale);

    ctx.fillStyle = CFG.background;
    ctx.fillRect(0, 0, width, height);

    return { node, ctx, scale };
  }

  function roundedRect(ctx, x, y, w, h, r) {
    const rr = Math.min(r, w / 2, h / 2);

    ctx.beginPath();
    ctx.moveTo(x + rr, y);
    ctx.arcTo(x + w, y, x + w, y + h, rr);
    ctx.arcTo(x + w, y + h, x, y + h, rr);
    ctx.arcTo(x, y + h, x, y, rr);
    ctx.arcTo(x, y, x + w, y, rr);
    ctx.closePath();
  }

  function drawFrame(ctx, width, height) {
    const inset = CFG.frameInset || 18;
    const radius = CFG.frameRadius || 22;

    ctx.save();

    ctx.strokeStyle = CFG.frameColor || "#d8d4cf";
    ctx.lineWidth = 2;
    roundedRect(
      ctx,
      inset,
      inset,
      width - inset * 2,
      height - inset * 2,
      radius
    );
    ctx.stroke();

    ctx.strokeStyle = CFG.frameInnerColor || "#ece8e3";
    ctx.lineWidth = 1;
    roundedRect(
      ctx,
      inset + 7,
      inset + 7,
      width - (inset + 7) * 2,
      height - (inset + 7) * 2,
      Math.max(0, radius - 5)
    );
    ctx.stroke();

    ctx.restore();
  }

  function wrap(ctx, text, width) {
    const lines = [];
    const paragraphs = String(text || "").split(/\n/);

    for (const paragraph of paragraphs) {
      if (!paragraph.trim()) {
        lines.push("");
        continue;
      }

      const words = paragraph.split(/\s+/);
      let line = "";

      for (const word of words) {
        const test = line ? `${line} ${word}` : word;

        if (!line || ctx.measureText(test).width <= width) {
          line = test;
        } else {
          lines.push(line);
          line = word;
        }
      }

      if (line) lines.push(line);
    }

    return lines;
  }

  function drawTextBlock(ctx, text, x, y, width, lineHeight) {
    const lines = wrap(ctx, text, width);
    let yy = y;

    for (const line of lines) {
      ctx.fillText(line, x, yy);
      yy += lineHeight;
    }

    return yy;
  }

  async function loadImage(url) {
    if (!url) return null;

    return new Promise(resolve => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => resolve(img);
      img.onerror = () => resolve(null);
      img.src = url;
    });
  }

  function drawCover(ctx, img, x, y, w, h) {
    if (!img) {
      ctx.fillStyle = CFG.soft;
      ctx.fillRect(x, y, w, h);
      return;
    }

    const scale = Math.max(w / img.width, h / img.height);
    const sw = w / scale;
    const sh = h / scale;
    const sx = (img.width - sw) / 2;
    const sy = (img.height - sh) / 2;

    ctx.drawImage(img, sx, sy, sw, sh, x, y, w, h);
  }

  async function drawLogo(ctx, width) {
    const img = await loadImage(window.JEN_PLAYHOUSE_LOGO_URL || CFG.logoUrl);
    if (!img) return;

    const maxH = 30;
    const maxW = 42;
    const scale = Math.min(maxW / img.width, maxH / img.height);
    const w = img.width * scale;
    const h = img.height * scale;
    const x = Math.round((width - w) / 2);
    const y = Math.round((CFG.logoBand - h) / 2) + 3;

    // Already matte charcoal: draw at full opacity so it stays crisp.
    ctx.drawImage(img, x, y, w, h);

    ctx.strokeStyle = CFG.line;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(CFG.side, CFG.logoBand - 1);
    ctx.lineTo(width - CFG.side, CFG.logoBand - 1);
    ctx.stroke();
  }

  async function drawAuthor(ctx, update, y) {
    const avatarSize = 58;
    const x = CFG.side;
    const avatar = await loadImage(getAvatar(update));

    ctx.save();
    ctx.beginPath();
    ctx.arc(x + avatarSize / 2, y + avatarSize / 2, avatarSize / 2, 0, Math.PI * 2);
    ctx.clip();
    drawCover(ctx, avatar, x, y, avatarSize, avatarSize);
    ctx.restore();

    const tx = x + avatarSize + 16;

    ctx.fillStyle = CFG.ink;
    ctx.font = f(22, 700);
    ctx.fillText(getName(update), tx, y + 24);

    // tiny verified badge
    const verifiedRaw = String(get(update, ["Verified", "verified"], "yes")).toLowerCase();
    if (["yes", "true", "1", "verified"].includes(verifiedRaw)) {
      const nw = ctx.measureText(getName(update)).width;

      ctx.fillStyle = "#7fb4d5";
      ctx.beginPath();
      ctx.arc(tx + nw + 15, y + 17, 7, 0, Math.PI * 2);
      ctx.fill();

      ctx.strokeStyle = "#fff";
      ctx.lineWidth = 1.6;
      ctx.beginPath();
      ctx.moveTo(tx + nw + 12, y + 17);
      ctx.lineTo(tx + nw + 14, y + 19);
      ctx.lineTo(tx + nw + 19, y + 14);
      ctx.stroke();
    }

    const meta = [getRole(update), getDate(update)].filter(Boolean).join(" · ");

    ctx.fillStyle = CFG.muted;
    ctx.font = f(14, 400);
    ctx.fillText(meta, tx, y + 47);

    return y + avatarSize;
  }

  function drawFooter(ctx, width, height) {
    const lineY = height - CFG.footer + 6;
    const textY = height - (CFG.frameInset || 18) - 14;

    ctx.save();

    ctx.strokeStyle = CFG.line;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(CFG.side, lineY);
    ctx.lineTo(width - CFG.side, lineY);
    ctx.stroke();

    ctx.fillStyle = CFG.muted;
    ctx.font = f(11, 400);
    ctx.textAlign = "left";
    ctx.textBaseline = "alphabetic";
    ctx.fillText(
      CFG.disclaimer,
      CFG.side,
      textY,
      width - CFG.side * 2
    );

    ctx.restore();
  }

  function textCardHeight(update, voice = false) {
    const probe = document.createElement("canvas").getContext("2d");
    probe.font = f(31, 400);

    const contentWidth = CFG.width - CFG.side * 2;
    const lines = wrap(probe, getText(update), contentWidth);
    const textHeight = Math.max(1, lines.length) * 42;

    // Text and voice-note cards stay adaptive, never forced to 4:5.
    const topArea = CFG.logoBand + 20 + 58;
    const authorToBodyGap = 12;
    const voiceBlock = voice ? 150 : 0;
    const safeGapBeforeFooter = 36;

    const naturalHeight =
      topArea +
      authorToBodyGap +
      textHeight +
      voiceBlock +
      safeGapBeforeFooter +
      CFG.footer;

    return Math.round(Math.max(330, naturalHeight));
  }

  async function renderText(update) {
    const height = textCardHeight(update, false);
    const { node, ctx } = canvas(CFG.width, height, 2);

    await drawLogo(ctx, CFG.width);

    let y = CFG.logoBand + 20;
    y = await drawAuthor(ctx, update, y);

    // Body/caption deliberately starts lower beneath the author/meta block.
    y += 40;

    ctx.fillStyle = CFG.ink;
    ctx.font = f(27, 400);

    drawTextBlock(
      ctx,
      getText(update),
      CFG.side,
      y,
      CFG.width - CFG.side * 2,
      38
    );

    drawFooter(ctx, CFG.width, height);
    drawFrame(ctx, CFG.width, height);
    return node;
  }

  function waveform(ctx, x, y, width, height) {
    const bars = 46;
    const gap = 5;
    const barW = (width - gap * (bars - 1)) / bars;

    ctx.fillStyle = CFG.muted;

    for (let i = 0; i < bars; i++) {
      const power =
        0.25 +
        0.75 * Math.abs(
          Math.sin(i * 0.62) *
          Math.cos(i * 0.29)
        );

      const bh = Math.max(5, height * power);
      ctx.fillRect(
        x + i * (barW + gap),
        y + (height - bh) / 2,
        barW,
        bh
      );
    }
  }

  async function renderVoice(update) {
    const height = textCardHeight(update, true);
    const { node, ctx } = canvas(CFG.width, height, 2);

    await drawLogo(ctx, CFG.width);

    let y = CFG.logoBand + 28;
    y = await drawAuthor(ctx, update, y);
    y += 22;

    if (getText(update)) {
      ctx.fillStyle = CFG.ink;
      ctx.font = f(28, 400);

      y = drawTextBlock(
        ctx,
        getText(update),
        CFG.side,
        y,
        CFG.width - CFG.side * 2,
        39
      ) + 18;
    }

    const boxX = CFG.side;
    const boxW = CFG.width - CFG.side * 2;
    const boxH = 112;

    ctx.fillStyle = CFG.soft;
    roundedRect(ctx, boxX, y, boxW, boxH, 18);
    ctx.fill();

    // Audio mark
    ctx.fillStyle = CFG.ink;
    ctx.beginPath();
    ctx.arc(boxX + 56, y + boxH / 2, 25, 0, Math.PI * 2);
    ctx.fill();

    // Mic icon
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.moveTo(boxX + 56, y + 36);
    ctx.lineTo(boxX + 56, y + 63);
    ctx.stroke();

    ctx.beginPath();
    ctx.arc(boxX + 56, y + 57, 12, 0, Math.PI);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(boxX + 56, y + 69);
    ctx.lineTo(boxX + 56, y + 78);
    ctx.stroke();

    waveform(ctx, boxX + 105, y + 34, boxW - 220, 44);

    ctx.fillStyle = CFG.muted;
    ctx.font = f(14, 400);
    ctx.textAlign = "right";
    ctx.fillText(getDuration(update) || "VOICE NOTE", boxX + boxW - 20, y + 62);
    ctx.textAlign = "left";

    drawFooter(ctx, CFG.width, height);
    drawFrame(ctx, CFG.width, height);
    return node;
  }

  async function renderMedia(update, url, kind, slideIndex = 0, totalSlides = 1) {
    // Photo / carousel / video ALWAYS stay 1080 × 1350.
    const { node, ctx } = canvas(CFG.width, CFG.mediaHeight);

    await drawLogo(ctx, CFG.width);

    // Keep the author compact.
    let y = CFG.logoBand + 20;
    y = await drawAuthor(ctx, update, y);
    y += 12;

    const x = CFG.side;
    const width = CFG.width - CFG.side * 2;
    const text = getText(update);
    const hasText = Boolean(text);

    // Caption belongs ABOVE the media, not in a separate blank block below it.
    if (hasText) {
      ctx.fillStyle = CFG.ink;
      ctx.font = f(22, 400);

      y = drawTextBlock(
        ctx,
        text,
        CFG.side,
        y,
        CFG.width - CFG.side * 2,
        31
      );

      y += 14;
    }

    // The media fills every remaining usable pixel down to the footer.
    const footerLineY = CFG.mediaHeight - CFG.footer + 6;
    const mediaBottom = footerLineY - 14;
    const mediaHeight = Math.max(240, mediaBottom - y);

    const img = await loadImage(url);
    drawCover(ctx, img, x, y, width, mediaHeight);

    if (kind === "video") {
      // Minimal video marker.
      ctx.fillStyle = "rgba(0,0,0,.50)";
      ctx.beginPath();
      ctx.arc(CFG.width / 2, y + mediaHeight / 2, 44, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#fff";
      ctx.beginPath();
      ctx.moveTo(CFG.width / 2 - 10, y + mediaHeight / 2 - 19);
      ctx.lineTo(CFG.width / 2 + 22, y + mediaHeight / 2);
      ctx.lineTo(CFG.width / 2 - 10, y + mediaHeight / 2 + 19);
      ctx.closePath();
      ctx.fill();
    }

    if (totalSlides > 1) {
      ctx.fillStyle = "rgba(0,0,0,.56)";
      roundedRect(ctx, x + width - 72, y + 14, 56, 30, 15);
      ctx.fill();

      ctx.fillStyle = "#fff";
      ctx.font = f(13, 600);
      ctx.textAlign = "center";
      ctx.fillText(
        `${slideIndex + 1}/${totalSlides}`,
        x + width - 44,
        y + 34
      );
      ctx.textAlign = "left";
    }

    drawFooter(ctx, CFG.width, CFG.mediaHeight);

    // Important: draw the frame against the WHOLE 4:5 canvas,
    // not the media area's local height.
    drawFrame(ctx, CFG.width, CFG.mediaHeight);

    return node;
  }

  function filename(update, suffix) {
    const raw = `${getName(update)}-${getDate(update) || "update"}-${suffix}`;

    return raw
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 90) + ".png";
  }

  function toBlob(canvasNode) {
    return new Promise((resolve, reject) => {
      canvasNode.toBlob(
        blob => blob ? resolve(blob) : reject(new Error("Could not create image.")),
        "image/png",
        1
      );
    });
  }

  async function save(canvasNode, name) {
    const safeName = String(name || "jen-play-house-update.png")
      .replace(/[\\/:*?"<>|]+/g, "-")
      .replace(/\s+/g, "-");

    const filename = safeName.endsWith(".png") ? safeName : `${safeName}.png`;

    function triggerDownload(href) {
      const a = document.createElement("a");
      a.href = href;
      a.download = filename;
      a.rel = "noopener";
      a.style.display = "none";
      document.body.appendChild(a);
      a.click();
      setTimeout(() => a.remove(), 1000);
    }

    // First choice: real PNG Blob.
    try {
      const blob = await new Promise((resolve, reject) => {
        if (typeof canvasNode.toBlob !== "function") {
          reject(new Error("Canvas toBlob is unavailable."));
          return;
        }

        canvasNode.toBlob(result => {
          if (result) resolve(result);
          else reject(new Error("Canvas returned an empty PNG blob."));
        }, "image/png");
      });

      const url = URL.createObjectURL(blob);
      triggerDownload(url);

      setTimeout(() => URL.revokeObjectURL(url), 5000);
      return;
    } catch (blobError) {
      console.warn("Blob download failed; using data URL fallback.", blobError);
    }

    // Fallback for browsers/local preview environments where toBlob fails.
    try {
      const dataUrl = canvasNode.toDataURL("image/png");
      if (!dataUrl || !dataUrl.startsWith("data:image/png")) {
        throw new Error("Canvas did not return a PNG data URL.");
      }

      triggerDownload(dataUrl);
      return;
    } catch (dataError) {
      console.error("PNG fallback also failed.", dataError);
      throw dataError;
    }
  }

  async function render(update = {}) {
    await document.fonts?.ready;

    const type = getType(update);
    const media = getMedia(update);

    if (type.includes("carousel")) {
      if (!media.length) throw new Error("Carousel post has no media.");

      const slides = [];
      for (let i = 0; i < media.length; i++) {
        slides.push(
          await renderMedia(update, media[i], "photo", i, media.length)
        );
      }
      return slides;
    }

    if (type.includes("video")) {
      const source = getThumbnail(update) || media[0];
      if (!source) throw new Error("Video post needs a thumbnail/poster.");

      return [
        await renderMedia(update, source, "video", 0, 1)
      ];
    }

    if (type.includes("voice") || type.includes("audio")) {
      return [await renderVoice(update)];
    }

    if (type.includes("photo") || type.includes("image")) {
      if (!media.length) throw new Error("Photo post has no media.");

      return [
        await renderMedia(update, media[0], "photo", 0, 1)
      ];
    }

    return [await renderText(update)];
  }

  async function exportUpdate(update = {}) {
    try {
    const type = getType(update);
    const outputs = await render(update);

    for (let i = 0; i < outputs.length; i++) {
      let suffix = "text";

      if (type.includes("carousel")) suffix = `carousel-${i + 1}`;
      else if (type.includes("video")) suffix = "video";
      else if (type.includes("voice") || type.includes("audio")) suffix = "voice-note";
      else if (type.includes("photo") || type.includes("image")) suffix = "photo";

      await save(outputs[i], filename(update, suffix));
    }

    } catch (error) {
      console.error("Jen update export failed:", error);
      throw error;
    }
  }

  window.JenUpdateCardExport = Object.freeze({
    export: exportUpdate,
    render,
    config: CFG
  });
})();
